import{z as s,x as B,o as E,c as d,q as r,j as A,D as t,d as e,s as n,S as o,b as l}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"端侧投机解码","description":"","frontmatter":{"title":"端侧投机解码","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/on-device-speculative.md","filePath":"llm/on-device-speculative.md","lastUpdated":1791063341000}'),p={name:"llm/on-device-speculative.md"};function m(T,a,C,h,u,c){const i=B("Mermaid");return E(),d("div",null,[a[2]||(a[2]=r('<h1 id="端侧投机解码" tabindex="-1">端侧投机解码 <a class="header-anchor" href="#端侧投机解码" aria-label="Permalink to &quot;端侧投机解码&quot;">​</a></h1><div class="epigraph"><p>草稿在设备上免费猜，云上大模型一次校验：接受规则仍可对准目标分布，省下的是跨网络的逐步往返，而不只是 GPU 上的串行步。</p><footer>—— Leviathan et al., Fast Inference from Transformers via Speculative Decoding, ICML 2023；草稿在本地见自投机与端侧小模型部署</footer></div><p><a href="/llm/edge-cloud-split">上一课</a>禁止每 token 往返。本课把<a href="/llm/speculative-decoding">投机解码</a>接到这条约束上：端上跑小模型或<a href="/llm/self-speculative-decoding">自投机</a>浅层，串行产生 \\(\\gamma\\) 个 token，一次送给云上目标做并行校验，返回接受前缀与可能的 residual 采样。无损仍相对云上目标。本课关闭「推理系统进阶」：从 KV 会计走到端侧，加速手段始终是减少目标逐步次数或搬字节。下一课程才是集群里的集合通信。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>端上小模型可以自己 generate，质量不够；云上大模型质量够，RTT×\\(T\\) 不可接受。标准投机假设草稿与目标在同一台机器、KV 共域。端云之间，草稿 KV 在端、目标 KV 在云，不能共享。缺口是：每轮上传 \\(\\gamma\\) 个 id（极轻）加当前前缀状态，云做一次宽查询前向，返回接受长度与一个 token。云上仍要为目标维护 KV，容量会计不变；省的是 <em>往返次数</em> 从 \\(T\\) 降到约 \\(T/\\mathbb{E}[k]\\)。</p><p>若草稿很弱，接受率低，每轮几乎只前进 1，RTT 几乎不降，还多付端上草稿能量。必须在设备上测接受率，不能用数据中心贪心投机数字。</p><p><span class="marginnote">温度、核、文法掩码必须在端云用同一协议，否则无损失败。端上 <a href="/llm/logit-bias">logit bias</a> 与云上不一致，是这类系统的典型 bug。</span></p><p><span class="marginnote">术语翻译：「接受规则」就是一套判定手段，用云上大模型算出的概率来逐个审核草稿 token——接受就白赚，拒绝就在拒绝处改由大模型重采一个，无论哪种结果，最终文字的分布都和直接用大模型生成完全一样。它是投机解码「无损」这句话的数学保证。</span></p><p><span class="marginnote">数字实例：设 RTT 为 200 毫秒、要生成 100 个 token。不用投机：100 次往返就是 20 秒纯网络等待。用端上草稿一次猜 \\(\\gamma=5\\)、平均接受 \\(k=3\\)（不含奖励 token，每轮实际前进 \\(k+1=4\\) 个）：往返次数降到约 \\(100/4=25\\) 次，约 5 秒——省的是网络等待，云上计算量几乎不变。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>端：量化小草稿或早退，<a href="/llm/sampler-kernel">采样器</a>在本地按产品 \\(T\\) 采样。云：目标模型一次前向校验 \\(\\gamma\\) 位置，实现与机内投机相同，见 Leviathan 接受规则。前缀要同步：拒绝后的 residual 在云上采，下发该 token，端追加。结构化确定边可在端上直接写、少问云，与<a href="/llm/structured-output-overhead">结构化开销</a>的确定边相同。层跳过自投机若目标也在端（整网本地），则无 RTT 问题，退化成设备内自投机，受 DRAM 限制。</p>',11)),(E(),A(o,null,{default:t(()=>[n(i,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20D%5B%22%E7%AB%AF%E4%B8%8A%E8%8D%89%E7%A8%BF%E4%B8%B2%E8%A1%8C%20%CE%B3%22%5D%20--%3E%20UP%5B%22%E4%B8%8A%E4%BC%A0%E8%8D%89%E7%A8%BF%20token%22%5D%0A%20%20UP%20--%3E%20V%5B%22%E4%BA%91%E4%B8%8A%E7%9B%AE%E6%A0%87%E4%B8%80%E6%AC%A1%E6%A0%A1%E9%AA%8C%22%5D%0A%20%20V%20--%3E%20ACC%5B%22%E6%8E%A5%E5%8F%97%E5%89%8D%E7%BC%80%20%2B%20residual%22%5D%0A%20%20ACC%20--%3E%20D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=l("h2",{id:"机制",tabindex:"-1"},[e("机制 "),l("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=l("p",null,[e("墙钟 \\(\\approx\\) 端上 \\(c_{\\mathrm{draft}}\\gamma\\) + 一次 RTT + 云上一次宽 decode。当 RTT 远大于云上逐步时，投机的主收益是少 RTT，甚至草稿比目标慢也可能赢——与机内「草稿必须更快」不同。这是端云投机特有的不等式。接受率随 \\(T\\) 降，思考模式更难加速。云上宽查询仍吃目标 KV，"),l("a",{href:"/llm/kv-cache-size-math"},"容量公式"),e("按用户数计，不按草稿计。")],-1)),a[5]||(a[5]=l("p",null,[l("a",{href:"/llm/flashattention"},"FlashAttention"),e(" 在云上校验拍 \\(n_q=\\gamma+1\\)，强度略升；端上草稿用 CPU/NPU 核，走本单元的量化路径。")],-1)),(E(),A(o,null,{default:t(()=>[n(i,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20subgraph%20OLD%5B%22%E4%B8%8D%E7%94%A8%E6%8A%95%E6%9C%BA%EF%BC%9A%E6%AF%8F%E4%B8%AA%20token%20%E4%B8%80%E6%AC%A1%E5%BE%80%E8%BF%94%22%5D%0A%20%20%20%20G1%5B%22%E7%AB%AF%E7%94%9F%E6%88%90%201%20token%22%5D%20--%3E%20C1%5B%22%E4%BA%91%E5%89%8D%E5%90%91%201%20%E6%AC%A1%22%5D%0A%20%20%20%20C1%20--%3E%20G1%0A%20%20end%0A%20%20subgraph%20NEW%5B%22%E7%94%A8%E6%8A%95%E6%9C%BA%EF%BC%9A%E6%AF%8F%E8%BD%AE%20%CE%B3%20%E4%B8%AA%20token%20%E4%B8%80%E6%AC%A1%E5%BE%80%E8%BF%94%22%5D%0A%20%20%20%20G2%5B%22%E7%AB%AF%E8%8D%89%E7%A8%BF%E6%9C%AC%E5%9C%B0%E7%8C%9C%20%CE%B3%20%E4%B8%AA%22%5D%20--%3E%20C2%5B%22%E4%BA%91%E4%B8%80%E6%AC%A1%E5%B9%B6%E8%A1%8C%E6%A0%A1%E9%AA%8C%22%5D%0A%20%20%20%20C2%20--%3E%20ACC%5B%22%E6%8E%A5%E5%8F%97%20k%20%E4%B8%AA%20%2B%20residual%201%20%E4%B8%AA%22%5D%0A%20%20%20%20ACC%20--%3E%20G2%0A%20%20end%0A%20%20OLD%20--%3E%7CRTT%20%E6%AC%A1%E6%95%B0%E7%BA%A6%20T%7C%20SLOW%5B%22%E7%BD%91%E7%BB%9C%E7%AD%89%E5%BE%85%20%3D%20T%20%C3%97%20RTT%22%5D%0A%20%20NEW%20--%3E%7CRTT%20%E6%AC%A1%E6%95%B0%E7%BA%A6%20T%2Fk%7C%20FAST%5B%22%E7%BD%91%E7%BB%9C%E7%AD%89%E5%BE%85%20%3D%20T%2Fk%20%C3%97%20RTT%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=r('<p><span class="marginnote">这张图回答的问题是：加速到底省在哪里。常见误区是以为省了云上计算——云上该算的一次没少，省的全是往返次数。推论是机内投机「草稿必须比目标快」的教条在端云场景失效：只要 RTT 够大，草稿慢一点、但每轮多前进几个 token，总墙钟仍然更短。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要在弱网、高抖动上假设 RTT 常数；应用自适应 \\(\\gamma\\)。不要把端上草稿的输出在拒绝前展示成最终文字（或明确标成草稿）。词表必须一致。本课程不把通信拓扑展开；Ring/Tree 从下一课程开始。</p><p>出处：Leviathan et al., ICML 2023；Draft &amp; Verify / LayerSkip 为草稿来源；Splitwise 为阶段拆分背景。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>端云投机用本地草稿减 RTT 次数；无损相对云上目标。</li><li>草稿与目标 KV 不共享；上传的是 token 不是 KV。</li><li>RTT 主导时，草稿甚至可以较慢仍赢。</li><li>采样、掩码、温度必须端云一致。</li><li>接受率要在设备与产品 \\(T\\) 上测。</li><li>推理系统进阶到此结束。</li><li>出处：Leviathan et al., ICML 2023。</li></ul>',6))])}const k=s(p,[["render",m]]);export{f as __pageData,k as default};
